Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include<iostream>
#include<cstdio>
#include<vector>
#include<algorithm>
#define ll long long
#define R register
using namespace std;
const int mod1=998244353,mod2=1e9+7;
inline ll read(){
	ll a=0,b=1;
	char s=getchar();
	while(s<48||s>57){
		if(s=='-') b=-1;
		s=getchar();
	}
	while(s>=48&&s<=57)
		a=(a<<1)+(a<<3)+s-48,s=getchar();
	return a*b;
}
ll n;
ll cnt1,sum[10];
vector<int> v[10];
void dfs1(int len,int val){
	if(len>6) return;
	v[len].push_back((cnt1-val+mod1)%mod1);
	sum[len]+=(cnt1-val+mod1)%mod1;
	++cnt1;
	for(R int i=0;i<=9;i=-~i) dfs1(len+1,val*10+i);
}
ll cnt2,ans;
inline bool check(ll x){return x*1000000+999999<=n&&x*10000000>n;}
int pw[7]={1,10,100,1000,10000,100000,1000000};
void dfs2(int len,ll val){
	if(val>n) return;
	if(check(val)){
		for(R int i=0;i<=6;i=-~i){
			ll v1=((cnt2+1-val*pw[i])%mod1+mod1)%mod1;
			int num=lower_bound(v[i].begin(),v[i].end(),mod1-v1)-v[i].begin();
			ans=(ans+(sum[i]+v[i].size()*v1-1LL*mod1*(v[i].size()-num)))%mod2;
		}
		cnt2+=cnt1;
	}
	else{
		if(len) ++cnt2;
		ans=(ans+((cnt2-val)%mod1+mod1)%mod1)%mod2;
		for(R int i=(!len);i<=9;i=-~i) dfs2(len+1,val*10+i);
	}
}
int main(){
	n=read();
	dfs1(0,0);
	for(R int i=0;i<=6;i=-~i) sort(v[i].begin(),v[i].end());
	dfs2(0,0);
	printf("%lld\n",ans);
	return 0;
}

